$ErrorActionPreference = 'Stop'
if (-not (Test-Path 'package.json')) {
    Write-Host 'ERROR: run from project root.' -ForegroundColor Red
    exit 1
}

# Delete the old server-side route handler — replaced by client page
$oldRoute = Join-Path -Path (Get-Location) -ChildPath 'app/auth/callback/route.ts'
if (Test-Path $oldRoute) {
    Remove-Item $oldRoute -Force
    Write-Host '  - app/auth/callback/route.ts (deleted)' -ForegroundColor Yellow
}

$files = @{}
$files['app/auth/callback/page.tsx'] = ''
$files['proxy.ts'] = ''

Write-Host '-> Patching auth callback to handle hash-flow tokens' -ForegroundColor Cyan
foreach ($path in $files.Keys) {
    $content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($files[$path]))
    $dir = Split-Path -Parent $path
    if ($dir -and -not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $fullPath = Join-Path -Path (Get-Location) -ChildPath $path
    [System.IO.File]::WriteAllText($fullPath, $content, [System.Text.UTF8Encoding]::new($false))
    Write-Host ('  + ' + $path) -ForegroundColor Green
}
Write-Host ''
Write-Host 'Done. Push and re-test the invite link.' -ForegroundColor Green